void HAL_UART_IRQHandler(UART_HandleTypeDef *huart)
{
  /* Simulate interrupt handling by calling appropriate callback functions */

  /* For receiver data ready scenario */
  if (huart->RxISR != NULL)
  {
    huart->RxISR(huart);
    return;
  }

  /* For transmission scenarios */
  if (huart->TxISR != NULL)
  {
    huart->TxISR(huart);
    return;
  }

  /* For error scenarios - call error callback */
  if (huart->ErrorCode != HAL_UART_ERROR_NONE)
  {
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    /*Call registered error callback*/
    huart->ErrorCallback(huart);
#else
    /*Call legacy weak error callback*/
    HAL_UART_ErrorCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
    return;
  }

  /* For IDLE event scenarios */
  if (huart->ReceptionType == HAL_UART_RECEPTION_TOIDLE)
  {
    uint16_t nb_rx_data = huart->RxXferSize - huart->RxXferCount;
    if ((huart->RxXferCount > 0U) && (nb_rx_data > 0U))
    {
      huart->RxEventType = HAL_UART_RXEVENT_IDLE;
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
      /*Call registered Rx Event callback*/
      huart->RxEventCallback(huart, nb_rx_data);
#else
      /*Call legacy weak Rx Event callback*/
      HAL_UARTEx_RxEventCallback(huart, nb_rx_data);
#endif /* (USE_HAL_UART_REGISTER_CALLBACKS) */
      return;
    }
  }

  /* For wakeup scenarios */
#if defined(USART_CR1_UESM)
#if defined(USART_CR3_WUFIE)
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    /* Call registered Wakeup Callback */
    huart->WakeupCallback(huart);
#else
    /* Call legacy weak Wakeup Callback */
    HAL_UARTEx_WakeupCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
    return;
#endif /* USART_CR3_WUFIE */
#endif /* USART_CR1_UESM */

  /* For transmission end scenarios */
  UART_EndTransmit_IT(huart);
}
